<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Factories\HasFactory;
class Vehicle extends Model { use HasFactory; protected $fillable=['name','slug','brand_id','model','year','category_id','transmission','fuel_type','seats','doors','mileage_policy','daily_price','weekly_price','monthly_price','weekend_price','holiday_price','deposit','driver_fee','extra_km_fee','late_return_fee','driver_available','self_drive_available','location_id','short_description','description','main_image','status','operational_status','odometer','registration_expires_at','insurance_expires_at','featured','sort_order']; protected function casts():array{return ['driver_available'=>'boolean','self_drive_available'=>'boolean','featured'=>'boolean','daily_price'=>'decimal:2','weekly_price'=>'decimal:2','monthly_price'=>'decimal:2','deposit'=>'decimal:2','registration_expires_at'=>'date','insurance_expires_at'=>'date'];} public function brand(){return $this->belongsTo(VehicleBrand::class,'brand_id');} public function category(){return $this->belongsTo(VehicleCategory::class,'category_id');} public function location(){return $this->belongsTo(Location::class);} public function images(){return $this->hasMany(VehicleImage::class)->orderBy('sort_order');} public function features(){return $this->belongsToMany(VehicleFeature::class, 'vehicle_feature_vehicle');} public function bookings(){return $this->hasMany(Booking::class);} public function maintenanceRecords(){return $this->hasMany(VehicleMaintenanceRecord::class)->latest('performed_at');} public function inspections(){return $this->hasMany(VehicleInspection::class)->latest('inspected_at');} }
